-- Preservar el resto del prompt y los otros playbooks.
UPDATE analisis_playbooks SET prompt=replace(prompt,'Regla clave: el margen % de cualquier grupo es sum(margen_bruto)/sum(ventas)*100, NUNCA el promedio de margen_bruto_pct.','Regla clave: usar analitica.margen_comercial(es_cpp,ventas,costo_comercial,margen_comercial,ventas_base_margen), que retorna JSON con pct, margen y costo. Laminados usa CPP de materia prima, las demás líneas conservan ERP. No estimar utilidad para Laminados sin CPP. Leer v_meta.corte_cpp_laminados: para comparar márgenes mensuales utilizar meses cerrados; el mes abierto tiene ventas pero CPP pendiente. NUNCA promediar margen_bruto_pct.') WHERE slug='margenes';
